SELECT id, organization_id, owner_id, code, name, path, default_decision_level, version_source, fallback_version, enabled,
       summary_status, summary, summary_error, summary_generated_at
FROM project p
WHERE p.id = #{id}
  AND p.deleted = 0
  AND (
    p.owner_id = #{ownerId}
    OR EXISTS (
        SELECT 1 FROM project_member pm
        WHERE pm.project_id = p.id AND pm.user_id = #{ownerId}
    )
  )

SELECT id, organization_id, owner_id, code, name, path, default_decision_level, version_source, fallback_version, enabled,
       summary_status, summary, summary_error, summary_generated_at
FROM project p
WHERE p.deleted = 0
  AND (
    p.owner_id = #{ownerId}
    OR EXISTS (
        SELECT 1 FROM project_member pm
        WHERE pm.project_id = p.id AND pm.user_id = #{ownerId}
    )
  )

    AND p.organization_id = #{organizationId}

ORDER BY p.id
